import{_ as r,o as a,c as e,a2 as o}from"./chunks/framework.BWuWLRhz.js";const p=JSON.parse('{"title":"使用者手冊","description":"","frontmatter":{},"headers":[],"relativePath":"zh-HK/user-guide/index.md","filePath":"zh-HK/user-guide/index.md","lastUpdated":1786468666000}'),s={name:"zh-HK/user-guide/index.md"};function n(l,t,i,h,g,d){return a(),e("div",null,[...t[0]||(t[0]=[o('<h1 id="使用者手冊" tabindex="-1">使用者手冊 <a class="header-anchor" href="#使用者手冊" aria-label="Permalink to &quot;使用者手冊&quot;">​</a></h1><p>Lertaro 是一款為 Windows 打造的、鍵盤優先的極速檔案檢索啓動器。它在後臺索引你的本地磁碟(NTFS 和 ReFS 通過各自的變更日誌，其他檔案系統則直接監聽變化)及網絡共享，讓你能在極短時間內跳轉到任意檔案、資料夾或應用程式。</p><p>本手冊涵蓋日常使用所需的一切：</p><ul><li><strong><a href="./getting-started.html">快速上手</a></strong> —— 安裝 Lertaro，瞭解它的三種搜尋視窗(主視窗/快速視窗/內嵌視窗)。</li><li><strong><a href="./search-syntax.html">搜尋語法</a></strong> —— 模糊匹配、排除/精確/前綴/後綴操作符、或組、盤符定向、路徑模式，以及中文檔案名的拼音別名匹配。</li><li><strong><a href="./hotkeys.html">熱鍵</a></strong> —— 每一個可配置快速鍵與硬編碼按鍵，及其預設綁定。</li><li><strong><a href="./actions-and-preview.html">動作選單與預覽</a></strong> —— 類右鍵選單的動作列表，以及 QuickLook 預覽視窗。</li><li><strong><a href="./space-analyzer.html">空間分析</a></strong> —— 基於現有索引快速呈現檔案與資料夾空間佔比的矩形樹。</li><li><strong><a href="./instant-answers.html">即時答案與關鍵詞功能</a></strong> —— 計算器、環境變量、運行命令這些捷徑，以及處理程序管理、視窗切換器、瀏覽器資料、設定搜尋、網頁搜尋、翻譯這類關鍵詞觸發的插件。</li><li><strong><a href="./cli.html">命令列搜尋（lff）</a></strong> —— 可以在終端裏使用的、fzf 風格的命令列伴侶工具。</li><li><strong><a href="./uri-protocol.html">URI 協議（lertaro://）</a></strong> —— 通過一個鏈接、別的程式或腳本，直接跳轉到某次搜尋或某項具體設定。</li><li><strong><a href="./file-manager-support.html">支援的檔案管理器</a></strong> —— Lertaro 可以嵌入、觸發快速導航、或檢測當前資料夾的檔案管理器和檔案選擇對話方塊都有哪些。</li><li><strong><a href="./settings/">設定項參考</a></strong> —— 每一個設定頁面、每一個 Tab、每一項設定，逐條列出。</li><li><strong><a href="./troubleshooting.html">故障排查</a></strong> —— 常見問題與解決辦法。</li><li><strong><a href="./donate.html">捐贈支持</a></strong> —— 如果 Lertaro 對你有幫助。</li></ul><p>如果是第一次配置 Lertaro，建議從<strong>快速上手</strong>開始閱讀。</p>',5)])])}const m=r(s,[["render",n]]);export{p as __pageData,m as default};
